schemas.schema-01_core.prisma:
/// [Customer Identity & Access] - Implements registration/authentication and Customer Role requirements from 03_ai_ecommerce_user_management.md. Each instance represents a person with customer capabilities (browsing, buying, reviewing, profile management). Enforces 3NF by linking to unique user profile and not duplicating profile/address info. Key relationships: ai_ecommerce_user_profiles (mandatory 1:1), ai_ecommerce_user_addresses (1:N), ai_ecommerce_user_oauth (1:N), ai_ecommerce_user_audit_logs (1:N). Behavioral notes: supports soft-deletion and unique email/oauth identity via related tables.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_customers {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique row identity; referenced throughout system. Immutable and atomic for all customer records.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 relation to ai_ecommerce_user_profiles; strictly normalized; unique required FK.
  profile_id String @db.Uuid

  /// [Created Timestamp] - For audit and traceability.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - For compliance tracking.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - If set, account is deactivated but retained for compliance; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  @@unique([profile_id])
}

/// [Seller Identity & Onboarding] - Fulfills seller onboarding, authentication, and identity requirements in 04_ai_ecommerce_seller_admin_management.md. Each record is a business account with seller privileges, strictly normalized with profile linkage. Key relationships: ai_ecommerce_user_profiles (mandatory 1:1), ai_ecommerce_user_addresses (1:N), ai_ecommerce_user_oauth (1:N), ai_ecommerce_user_audit_logs (1:N). Seller approval states handled in dedicated onboarding tables. Not duplicated across profiles. Behavioral notes: soft-delete for business user deactivation.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_sellers {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique seller identity for business account; referenced in all seller business flows.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 relation to ai_ecommerce_user_profiles; unique required FK.
  profile_id String @db.Uuid

  /// [Created Timestamp] - For audit/compliance.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - Tracks changes/audits.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Set if seller account is inactive (audit/compl.), null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_seller_business_profiles ai_ecommerce_seller_business_profiles?
  ai_ecommerce_seller_onboarding_logs ai_ecommerce_seller_onboarding_logs[]
  ai_ecommerce_seller_verification_documents ai_ecommerce_seller_verification_documents[]
  ai_ecommerce_admin_action_logs ai_ecommerce_admin_action_logs[]
  ai_ecommerce_products ai_ecommerce_products[]

  @@unique([profile_id])
}

/// [Administrator Identity] - Implements admin role/account separation (03_ai_ecommerce_user_management.md, 04_ai_ecommerce_seller_admin_management.md). Only platform admins—distinct from sellers/customers. Strictly normalized: one profile per admin. Key relationships: ai_ecommerce_user_profiles (mandatory 1:1), ai_ecommerce_user_audit_logs (1:N). Use: Action/audit log linkage, privilege separation. Notes: Only admin-privileged users reside here.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_administrators {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique admin identity; referenced in admin/audit flows.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 relation to ai_ecommerce_user_profiles; unique per admin.
  profile_id String @db.Uuid

  /// [Created Timestamp] - Created for traceability.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - Compliance/audit edits.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Admin deactivation timestamp; null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_seller_onboarding_logs ai_ecommerce_seller_onboarding_logs[]
  ai_ecommerce_admin_action_logs ai_ecommerce_admin_action_logs[]

  @@unique([profile_id])
}

/// [User Profile] - Implements core profile for customer, seller, admin per 03_ai_ecommerce_user_management.md & 04_ai_ecommerce_seller_admin_management.md, with display, comms, and privacy settings. Strict 3NF: never duplicated (referenced by all identity tables). Central for self-service updates, comms config, and unique email identity. Behavioral notes: flexible optional fields, system-wide email uniqueness enforced here. Key relationships: referenced everywhere user profile needed.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_profiles {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - One-to-one with every user/seller/admin identity.
  id String @id @db.Uuid

  /// [Display Nickname] - User-facing display name (not unique).
  nickname String

  /// [Profile Image] - Optional (avatar or profile photo).
  avatar_uri String? @db.VarChar(80000)

  /// [Email Address] - System-wide unique (communication & login).
  email String

  /// [Phone Number] - Optionally supplied for comms channels/MFA.
  phone_number String?

  /// [Communication Consent] - Explicit opt-in for platform messaging.
  communication_consent Boolean

  /// [Created Timestamp] - Compliance/audit trails.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last profile update.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_customers ai_ecommerce_customers?
  ai_ecommerce_sellers ai_ecommerce_sellers?
  ai_ecommerce_administrators ai_ecommerce_administrators?
  ai_ecommerce_user_addresses ai_ecommerce_user_addresses[]
  ai_ecommerce_user_oauth ai_ecommerce_user_oauth[]
  ai_ecommerce_user_audit_logs ai_ecommerce_user_audit_logs[]

  @@unique([email])
  @@index([nickname(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [User Addresses] - Implements normalized delivery/billing/multi-address per 03_ai_ecommerce_user_management.md. 1:N with ai_ecommerce_user_profiles (profile_id FK). Flexible for domestic/international. Not repeated in parent. Behavioral: Soft delete for audit, region validation handled elsewhere. Examples: Used at checkout/order, customer address book.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_addresses {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique address, referenced by fulfillment etc.
  id String @id @db.Uuid

  /// [Profile FK] - Owner of address; 1:N relationship from profile.
  profile_id String @db.Uuid

  /// [Address Type] - 'default', 'billing', or 'delivery'; logical separation.
  address_type String

  /// [Recipient Name] - Who will receive item at this address.
  name String

  /// [Recipient Phone] - Delivery contact number.
  phone_number String

  /// [Postal Code] - Delivery area postal code (FMS, INTL OK).
  postal_code String

  /// [Main Address Line] - Street/road/building etc.
  address_line1 String

  /// [Secondary Address Line] - Apartment/unit/floor, optional.
  address_line2 String?

  /// [Custom Label] - User-supplied e.g. 'Work', 'Mom's house'.
  custom_label String?

  /// [Region/Country Code] - ISO/country/region/locale code as required.
  region_code String

  /// [Default Address] - True if active default; service enforced.
  is_default Boolean

  /// [Created Timestamp] - Record creation date/time.
  created_at DateTime @db.Timestamptz

  /// [Last Edited Timestamp] - Compliance/audit trail.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Timestamp of soft delete/null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  @@index([profile_id])
}

/// [User OAuth Account] - Fulfills single/external sign-on per 03_ai_ecommerce_user_management.md. 1:N for providers per user profile. Model is normalized, each record one provider-user pair. Key: Uniqueness by provider+provider_user_id. Used for federated identity/login/account linking, never for regular credential storage. Behavioral: unique composite PK for anti-duplication.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_oauth {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique for OAuth account association/audit.
  id String @id @db.Uuid

  /// [Profile FK] - Links OAuth to user's profile (1:N).
  profile_id String @db.Uuid

  /// [Auth Provider] - e.g. 'google', 'apple', 'kakao', etc.
  provider String

  /// [Provider User ID] - Unique in provider namespace.
  provider_user_id String

  /// [Binding Created] - When account linkage made/audited.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  @@index([profile_id])

  @@unique([provider, provider_user_id])
}

/// [User Audit Log] - Implements sensitive action/trace requirements in 03_ai_ecommerce_user_management.md; logs changes, logins, security events. 3NF-compliant: all actionable events in this log, never duplicated in main profile tables. Behavioral: Write-once/append-only (no delete allowed), event code/JSON in payload, links to acting user profile. Typical: Tracks login, registration, reset, account changes, compliance events.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_audit_logs {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - One-to-each audit event; globally unique.
  id String @id @db.Uuid

  /// [Profile FK] - Traces event actor.
  profile_id String @db.Uuid

  /// [Audit Event Type] - 'registration', 'login', 'profile_update', etc. Coded by API/service.
  event_type String

  /// [Payload] - Opaque log info/context (e.g. IP, device, JSON payload).
  event_payload String?

  /// [Log Created] - Exact time event happened.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profiles @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  @@index([profile_id, event_type, created_at])
}

/// [Customer Identity & Access] - This implements the user identity, registration/authentication, and customer role management requirements from 03_ai_ecommerce_user_management.md. 
///
/// Enables individuals to act as customers—browsing, ordering, reviewing—through a normalized identity linked 1:1 with user profile for account management. Strict 3NF ensures profile/address/oauth are never duplicated here. For example, used as owner of a cart, order, or review.
///
/// Key relationships: ai_ecommerce_user_profile (1:1 required), ai_ecommerce_user_address (indirect 1:N), ai_ecommerce_user_oauth (indirect 1:N).
/// Special behaviors: Supports soft delete for compliance/audit.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_customer {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique customer row identity. Immutable and atomic for all customer records.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 per customer. Enforces strict 3NF and never duplicates profile info. Unique required FK.
  profile_id String @db.Uuid

  /// [Created Timestamp] - For audit and traceability of customer account lifecycle.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - Compliance tracking for all modifications.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - If set, account is deactivated (compliance), null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profile @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_inquiry ai_ecommerce_inquiry[]
  ai_ecommerce_review ai_ecommerce_review[]
  ai_ecommerce_forum_thread ai_ecommerce_forum_thread[]
  ai_ecommerce_comment ai_ecommerce_comment[]
  ai_ecommerce_report ai_ecommerce_report[]
  ai_ecommerce_inquiry_snapshot ai_ecommerce_inquiry_snapshot[]
  ai_ecommerce_review_snapshot ai_ecommerce_review_snapshot[]
  mv_community_last_activity mv_community_last_activity[]
  ai_ecommerce_cart ai_ecommerce_cart[]
  ai_ecommerce_order ai_ecommerce_order[]
  ai_ecommerce_return_request ai_ecommerce_return_request[]
  ai_ecommerce_coupon ai_ecommerce_coupon[]
  ai_ecommerce_loyalty_point ai_ecommerce_loyalty_point[]
  ai_ecommerce_wallet ai_ecommerce_wallet[]
  ai_ecommerce_favorite ai_ecommerce_favorite[]
  ai_ecommerce_favorite_tag ai_ecommerce_favorite_tag[]
  ai_ecommerce_recommendation ai_ecommerce_recommendation[]
  ai_ecommerce_snapshot ai_ecommerce_snapshot[]
  ai_ecommerce_personalization_config ai_ecommerce_personalization_config[]
  ai_ecommerce_personalization_analytics ai_ecommerce_personalization_analytics[]
  ai_ecommerce_audit_logs ai_ecommerce_audit_logs[]
  ai_ecommerce_audit_log ai_ecommerce_audit_log[]

  @@unique([profile_id])
}

/// [Seller Identity & Onboarding] - This implements seller onboarding, authentication, and business identity requirements from 04_ai_ecommerce_seller_admin_management.md. 
///
/// Each record is a business user linked 1:1 to a unique profile. Strict normalization; all business attributes stored in relevant business profile tables. Used for seller product, catalog, and coupon ownerships.
///
/// Key relationships: ai_ecommerce_user_profile (1:1 required).
/// Special behaviors: Soft delete for business user deactivation.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_seller {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique seller identity for business account; globally referenced.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 relation for normalized seller account. Unique required FK.
  profile_id String @db.Uuid

  /// [Created Timestamp] - For compliance and audit trails.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - Change tracking and audits.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Marks deactivated seller account, null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profile @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_seller_business_profile ai_ecommerce_seller_business_profile?
  ai_ecommerce_seller_onboarding_log ai_ecommerce_seller_onboarding_log[]
  ai_ecommerce_seller_verification_document ai_ecommerce_seller_verification_document[]
  ai_ecommerce_admin_action_log ai_ecommerce_admin_action_log[]
  ai_ecommerce_product ai_ecommerce_product[]
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_coupon ai_ecommerce_coupon[]
  ai_ecommerce_audit_logs ai_ecommerce_audit_logs[]
  ai_ecommerce_audit_log ai_ecommerce_audit_log[]

  @@unique([profile_id])
}

/// [Administrator Identity] - This model implements administrator account management per 03_ai_ecommerce_user_management.md and 04_ai_ecommerce_seller_admin_management.md. 
///
/// Represents system-level privileged users for operations, onboarding, and audit. Strictly normalized to have 1:1 linkage to profile. Used for audit logs and platform controls.
///
/// Key relationships: ai_ecommerce_user_profile (1:1 required).
/// Special behaviors: Profile association required; record is soft deleted upon admin removal.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_administrator {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique administrator identity for platform ops.
  id String @id @db.Uuid

  /// [User Profile Relation] - 1:1 admin-profile for RBAC/audit. Unique FK.
  profile_id String @db.Uuid

  /// [Created Timestamp] - Traceability for admin privileges.
  created_at DateTime @db.Timestamptz

  /// [Last Updated Timestamp] - Regulatory audit support.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Deactivation time if revoked; otherwise null.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profile @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_seller_onboarding_log ai_ecommerce_seller_onboarding_log[]
  ai_ecommerce_admin_action_log ai_ecommerce_admin_action_log[]
  ai_ecommerce_reply ai_ecommerce_reply[]
  ai_ecommerce_report ai_ecommerce_report[]
  ai_ecommerce_moderation_action ai_ecommerce_moderation_action[]
  ai_ecommerce_personalization_config ai_ecommerce_personalization_config[]
  ai_ecommerce_personalization_analytics ai_ecommerce_personalization_analytics[]
  ai_ecommerce_audit_logs ai_ecommerce_audit_logs[]
  ai_ecommerce_compliance_audits ai_ecommerce_compliance_audits[]
  ai_ecommerce_audit_log ai_ecommerce_audit_log[]
  ai_ecommerce_compliance_audit ai_ecommerce_compliance_audit[]

  @@unique([profile_id])
}

/// [User Profile] - Implements the unified user profile for customer, seller, and admin per 03_ai_ecommerce_user_management.md & 04_ai_ecommerce_seller_admin_management.md. Contains core display, communication, and consent fields. Strict 3NF: no duplication in referencing entities. Used as the anchor for authentication, contact, and privacy management.
///
/// Key relationships: Linked from identity/account tables; referenced for address, OAuth, audit logs.
/// Special behaviors: System-wide unique email constraint enforced here.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_profile {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - One-to-one with every customer, seller, admin record.
  id String @id @db.Uuid

  /// [Display Nickname] - User's public display name, shown system-wide. Not globally unique, no duplication in this record.
  nickname String

  /// [Profile Image URI] - Optional profile photo/avatar. Null acceptable as enforced field.
  avatar_uri String? @db.VarChar(80000)

  /// [Email Address] - Unique across platform. Used for login and comms. Global unique enforced in this table.
  email String

  /// [Phone Number] - Optional, for MFA or comms purposes. Not required.
  phone_number String?

  /// [Communication Consent] - Explicit opt-in preference (true if allowed to contact).
  communication_consent Boolean

  /// [Created Timestamp] - For compliance, audit, profile lifecycle.
  created_at DateTime @db.Timestamptz

  /// [Updated Timestamp] - Last edit time; audit and privacy tracking.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_customer ai_ecommerce_customer?
  ai_ecommerce_seller ai_ecommerce_seller?
  ai_ecommerce_administrator ai_ecommerce_administrator?
  ai_ecommerce_user_address ai_ecommerce_user_address[]
  ai_ecommerce_user_audit_log ai_ecommerce_user_audit_log[]

  @@unique([email])
  @@index([nickname(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [User Addresses] - Implements normalized delivery, billing, and multi-address requirements per 03_ai_ecommerce_user_management.md. Allows each profile to maintain one or more addresses, linked 1:N via profile_id. Handles region, label, and usage type atomically for compliance. Used during checkout, order, and user profile scenarios. 3NF compliant: address types and fields are atomic and never embedded in parent tables.
///
/// Key relationships: ai_ecommerce_user_profile (FK).
/// Special behaviors: Soft delete for audit/compliance, and logical address type enforcement.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_address {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique address ID for delivery/billing identity.
  id String @id @db.Uuid

  /// [Profile FK] - Each address is linked to a single user profile; 1:N. Non-null, non-unique.
  profile_id String @db.Uuid

  /// [Address Type] - Either 'default', 'delivery', or 'billing', enforced at service level.
  address_type String

  /// [Recipient Name] - Used for labeling delivery/billing party.
  name String

  /// [Recipient Phone] - Used for delivery contact.
  phone_number String

  /// [Postal Code] - Postal/ZIP for address validation/shipping.
  postal_code String

  /// [Address Line 1] - Main street/building/number.
  address_line1 String

  /// [Address Line 2] - Optional, apt/unit/floor/extra info.
  address_line2 String?

  /// [Custom Label] - Optional display, e.g. 'Home', 'Work'. Null permitted.
  custom_label String?

  /// [Region Code] - ISO/country/localization for shipping compliance.
  region_code String

  /// [Default Address] - True if this address is user-selected default address. Unique enforced at service level, not schema.
  is_default Boolean

  /// [Created Timestamp] - Record creation/tracking.
  created_at DateTime @db.Timestamptz

  /// [Last Edited Timestamp] - For audit trail, compliance.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Soft deletion for compliance while retaining record.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profile @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  ai_ecommerce_order ai_ecommerce_order[]

  @@index([profile_id])
}

/// [User Audit Log] - Implements audit-logging of sensitive user events (registration, logins, profile updates) per 03_ai_ecommerce_user_management.md. All actionable events are written here; never stored in identity/profile tables. Strictly write-once/append-only, for post-facto investigation and compliance. Example: Tracks login attempts, registration, resets, permission changes. 3NF-compliant and normalized.
///
/// Key relationships: ai_ecommerce_user_profile (actor FK).
/// Special behaviors: All mutation events recorded as immutable audit entries; not deleted/updated.
///
/// @namespace Core
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_user_audit_log {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique for every audit event logged.
  id String @id @db.Uuid

  /// [Profile FK] - Traces event to acting user profile (required).
  profile_id String @db.Uuid

  /// [Audit Event Type] - Coded type, e.g., 'registration', 'login', 'profile_update'.
  event_type String

  /// [Payload] - JSON/text or null; for event context (e.g. device/IP).
  event_payload String?

  /// [Log Created] - Time event was recorded for compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  profile ai_ecommerce_user_profile @relation(fields: [profile_id], references: [id], onDelete: Cascade)

  @@index([profile_id, event_type, created_at])
}

schemas.schema-02_seller_admin.prisma:
/// [Seller Business Profile Model] - This implements the seller business profile requirement from the Seller/Admin Management specification (see onboarding, compliance, and privilege separation section in the requirements analysis).
///
/// This model stores structured business profile details for each seller to facilitate onboarding, verification and regulatory compliance. Maintains 3NF normalization by separating business information from user accounts/identity details, ensuring adaptability to various business registration workflows. For example, it is used to store business registration info, tax ID, company details, and state throughout onboarding.
///
/// Key relationships: references ai_ecommerce_sellers for its 1:1 link to the seller. Referenced by ai_ecommerce_seller_onboarding_logs and ai_ecommerce_seller_verification_documents for audit compliance tracking.
/// Special behaviors: Only one business profile per seller. Profile can be soft-deleted and must be auditable for compliance.
///
/// @namespace SellerAdmin
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_seller_business_profiles {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Uniquely identifies the seller business profile record. Implements the business profile requirement for unique, auditable identification of seller registration data. Required for normalized, atomic key structure.
  id String @id @db.Uuid

  /// [Seller linkage] - Links to ai_ecommerce_sellers. Implements requirement to associate each business profile to the seller account. Maintains normalization by storing only the reference, not duplicated seller data. For example, used during onboarding or audits to fetch the seller.
  seller_id String @db.Uuid

  /// [Business name] - Implements business identification aspect. The registered name of seller's company. Ensures atomicity and separation from user identity.
  business_name String

  /// [Business reg. number] - Implements regulatory compliance. Stores the unique government-issued business number. Required for audit. 3NF: all business info relates only to its own profile.
  business_registration_number String

  /// [Tax ID] - Implements taxation compliance requirement. Holds unique business tax identifier. Maintains normalized, atomic structure and ensures auditability.
  tax_id String?

  /// [Contact name] - Implements business contact point. The official representative for business queries. Keeps contact data atomic, separated from business legal records.
  contact_name String

  /// [Contact phone] - Implements primary contact info. Used for onboarding, support, and compliance calls. Properly atomic with no embedded objects.
  contact_phone String

  /// [Contact email] - Implements contact traceability requirement. Business communication endpoint. Not user email, always business-specific. Properly normalized.
  contact_email String

  /// [Business address 1] - Implements physical presence requirement. First address line. Kept atomic to meet normalization. No embedded geolocations.
  address_line1 String

