  customer_id String @db.Uuid

  /// [Product Reference] - References the product marked as favorite. Strictly one product per favorite. Example: a customer favorites a specific product.
  product_id String @db.Uuid

  /// [Favorite Tag Reference] - Optionally references a tag to categorize this favorite. 3NF-compliant, tags separated from favorite entry. Example: grouping favorites under 'Gift Ideas' tag.
  favorite_tag_id String? @db.Uuid

  /// [Created Timestamp] - Timestamp when the favorite was created. Immutable audit field.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)
  favorite_tag ai_ecommerce_favorite_tag? @relation(fields: [favorite_tag_id], references: [id], onDelete: Cascade)

  @@unique([customer_id, product_id])
  @@index([product_id])
  @@index([favorite_tag_id])
}

/// [Favorite Tag Entity] - Implements 'Tagging & Organization' from personalization requirements. Lets customers group favorites by tag. Maintains 3NF by storing only tag name/ownership. Example: tags like 'Wishlist', 'Gift', 'To Buy'. Key relation: links to ai_ecommerce_customer; tag name unique per-customer.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_favorite_tag {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique UUID for user tag. Required for tag referencing in favorites.
  id String @id @db.Uuid

  /// [Tag Owner Reference] - Points to the customer who owns this tag. Each customer can name tags independently.
  customer_id String @db.Uuid

  /// [Tag Name] - The customer-defined label for this grouping. Strictly unique per customer. Example: 'For Mom'.
  name String

  /// [Created Timestamp] - When the tag was created first. Auditable and 3NF-compliant.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_ecommerce_favorite ai_ecommerce_favorite[]

  @@unique([customer_id, name])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Personalized Recommendation Entity] - Implements 'Personalized Recommendations' from the requirements. Stores system-generated recommendations for a user and product, no derived or computed data. Maintains atomic links to customer, recommended product, optional snapshot. For example: logging a daily AI suggestion for a product. Special: one record per customer-product-timestamp, 3NF. References ai_ecommerce_customer, ai_ecommerce_product, ai_ecommerce_snapshot.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_recommendation {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique identifier for this recommendation entry.
  id String @id @db.Uuid

  /// [Recommendation recipient] - The customer that gets this recommendation.
  customer_id String @db.Uuid

  /// [Recommended product] - The product being recommended for this user.
  product_id String @db.Uuid

  /// [Recommendation context snapshot] - Links to personalization snapshot that informed this recommendation, if present.
  snapshot_id String? @db.Uuid

  /// [Recommended Timestamp] - When the recommendation was created by the system.
  recommended_at DateTime @db.Timestamptz

  /// [Reason Code] - AI-generated string indicating why this was recommended (e.g., 'similar_items'). Null for standard recommendations.
  reason_code String?

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)
  snapshot ai_ecommerce_snapshot? @relation(fields: [snapshot_id], references: [id], onDelete: Cascade)

  @@index([product_id])
  @@index([snapshot_id])

  @@unique([customer_id, product_id, recommended_at])
  @@index([recommended_at])
  @@index([reason_code(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Personalization Snapshot Entity] - Implements 'Snapshotting & Portability'. Records a user's personalization state snapshot. Only atomic properties captured, no aggregates. Used for restoring preferences/favorites (cross-device). Key: references ai_ecommerce_customer. Example: periodic backup or device sync snapshot.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_snapshot {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique snapshot event id.
  id String @id @db.Uuid

  /// [Customer Reference] - Who this snapshot is for.
  customer_id String @db.Uuid

  /// [Snapshot Type] - Describes captured data, e.g. 'favorites', 'settings', 'tags'.
  snapshot_type String

  /// [Taken Timestamp] - When the snapshot was taken.
  taken_at DateTime @db.Timestamptz

  /// [Blob Storage URI] - Location (usually cloud URI) of the full snapshot data.
  blob_uri String @db.VarChar(80000)

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_ecommerce_recommendation ai_ecommerce_recommendation[]

  @@unique([customer_id, snapshot_type, taken_at])
  @@index([snapshot_type(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Personalization Config Entity] - Implements admin/user-level personalization system parameters. Only atomic config keys, never status or results. Example: AI model version, tuning parameter. Key relationships: ai_ecommerce_administrator (who set), customer optional. Maintains strict 3NF (config_key/value pairs, not aggregates).
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_personalization_config {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique system-generated id for this config row.
  id String @id @db.Uuid

  /// [Admin Reference] - Who set/applied this config.
  admin_id String @db.Uuid

  /// [Customer Reference] - Optionally, per-user config. Null if global/system config.
  customer_id String? @db.Uuid

  /// [Config Key] - Name specifying which setting is being applied.
  config_key String

  /// [Config Value] - Value associated with config key, usually string or URI.
  config_value String

  /// [Applied Timestamp] - When config went into effect.
  applied_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin ai_ecommerce_administrator @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  customer ai_ecommerce_customer? @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  @@unique([customer_id, config_key, applied_at])
  @@index([admin_id])
}

/// [Personalization Analytics Entity] - Implements atomic logging of personalization/favorite/recommendation engagement for analytics, never aggregates. For meaningful reporting/audits. Links: ai_ecommerce_customer (actor), ai_ecommerce_administrator (optional analyzer), ai_ecommerce_product (for event context). Usage: logging clicks, adding/removing favorite, etc. Strict 3NF, one row per action/event.
///
/// @namespace Personalization
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_personalization_analytics {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique analytics event id (UUID).
  id String @id @db.Uuid

  /// [Customer Reference] - Who triggered event.
  customer_id String @db.Uuid

  /// [Admin Reference] - Optional administrator involved in analytics/audit.
  admin_id String? @db.Uuid

  /// [Product Reference] - Contextual product attached to the event.
  product_id String? @db.Uuid

  /// [Event Type] - e.g., 'favorite_add', 'favorite_remove', 'rec_click'.
  event_type String

  /// [Event Occurrence] - When analytics event happened.
  event_at DateTime @db.Timestamptz

  /// [Details JSON] - Arbitrary serialized JSON for extensible event data.
  details_json String?

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  admin ai_ecommerce_administrator? @relation(fields: [admin_id], references: [id], onDelete: Cascade)
  product ai_ecommerce_product? @relation(fields: [product_id], references: [id], onDelete: Cascade)

  @@index([customer_id])
  @@index([admin_id])
  @@index([product_id])

  @@index([event_type])
  @@index([event_at])
  @@index([details_json(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-08_audit_analytics.prisma:
/// [Platform Audit Log] - This implements platform-wide audit requirements from the compliance and system documentation. 
///
/// The purpose of this model is to capture all major user/system actions across the platform for traceability and legal/audit purposes. Maintains 3NF by only recording atomic events; all aggregates must be computed externally. Example: Storing each API call, role change, data update. 
///
/// Key relationships: related to users (customer, seller, admin) via polymorphic actor fields, and can reference event objects by foreign keys. Special behaviors: Immutable records, soft deletion for audit compliance.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_audit_logs {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique identifier requirement.
  /// A UUID uniquely identifies each audit record, providing a tamper-proof anchor for traceability.
  id String @id @db.Uuid

  /// [Polymorphic Actor Customer FK] - Implements actor auditing for customers.
  /// Links the log entry to the customer entity if the action was taken by a customer. Maintains normalization by referencing only the actor’s id, not repeating user data.
  /// Optional; null unless the action came from a customer.
  actor_customer_id String? @db.Uuid

  /// [Polymorphic Actor Seller FK] - Implements actor auditing for sellers.
  /// Links the action to a seller when relevant, preserving entity relationships without redundancy.
  /// Nullable for non-seller actions.
  /// Maintains normalized linkage.
  actor_seller_id String? @db.Uuid

  /// [Polymorphic Actor Admin FK] - Implements admin action source traceability.
  /// Enforces role-based normalization by relating each admin action to the admin entity without duplicating data.
  /// Nullable when not an admin action.
  actor_admin_id String? @db.Uuid

  /// [Action Type] - Implements action type requirement.
  /// Atomic indicator of the type of event ("login", "update_order", etc.)
  /// Remains normalized as a primitive value for query/aggregation.
  action_type String

  /// [Target Table] - Implements audit context requirement.
  /// Identifies which business table/entity is affected (e.g., "ai_ecommerce_order"). Ensures normalization; does not store denormalized object state.
  target_table String

  /// [Target Entity FK] - Implements object-focused audit linking.
  /// Stores the UUID of the affected entity. Used for join/audit search.
  /// Remains atomic, normalized.
  target_id String @db.Uuid

  /// [Description/Details] - Implements detailed audit record context.
  /// Stores a brief, atomic note about the audit event. Example: "Order cancelled by admin." Purely descriptive.
  description String

  /// [Creation Timestamp] - Implements temporal logging requirement.
  /// Record of when the event occurred. Required for compliance and audit sequencing.
  created_at DateTime @db.Timestamptz

  /// [Soft Delete Timestamp] - Soft-deletion audit field, enables logical removal while maintaining audit trail. Stays null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer? @relation(fields: [actor_customer_id], references: [id], onDelete: Cascade)
  seller ai_ecommerce_seller? @relation(fields: [actor_seller_id], references: [id], onDelete: Cascade)
  admin ai_ecommerce_administrator? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)

  @@index([actor_customer_id, created_at])
  @@index([actor_seller_id, created_at])
  @@index([actor_admin_id, created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [System Events] - This implements system-level event tracking from the architecture and event orchestration requirements.
///
/// Used to persist domain and integration events (e.g., "order_created", "payment_captured") supporting event-driven design, compliance, debug traceability. 3NF is maintained—no aggregates or blobs; only atomic event info is captured. Example: recording "review_posted" event for async processing.
///
/// Key relationships: Possible link to orders/products/users by target_id; system event logs can be externally correlated with business tables. Special behaviors: Append-only, never updated/deleted except for rare compliance removal.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_system_events {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique event record identifier implementing append-only event log design.
  id String @id @db.Uuid

  /// [Event Type] - Implements event kind, e.g., "order_created". Atomic, normalized.
  event_type String

  /// [Target Table] - Table/entity impacted by event; for cross-domain analytics without denormalization.
  target_table String

  /// [Target ID] - UUID of affected row/entity. Maintains joinability.
  target_id String @db.Uuid

  /// [Event Payload] - JSON-encoded atomic event payload. Maintains normalization by not embedding related rows; only the raw event data.
  payload_json String

  /// [Event Created] - Timestamp for event append log.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_type, created_at])
  @@index([payload_json(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Compliance Audit Record] - Implements regulatory compliance logging and audit rule enforcement from the compliance documentation.
///
/// Captures all compliance-relevant events (policy updates, privacy requests, financial reviews) for legal defensibility. Maintains strict normalization: all compliance actions atomic, no pre-computed summaries.
/// Example: capturing "GDPR erase request", "PCI review", etc.
///
/// Key relationships: May reference administrators or user actions by foreign key. Special behaviors: (1) Tamper-evident, (2) direct role-to-event mapping.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_compliance_audits {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Compliance audit record UUID.
  id String @id @db.Uuid

  /// [Administrator FK] - Admin responsible for compliance action.
  /// Links to administrator (if available) for actor tracking. Maintains normalized responsibility representation.
  admin_id String? @db.Uuid

  /// [Audit Type] - E.g., "GDPR_Delete", "PCI_Review". Atomic. Normalized for query.
  audit_type String

  /// [Subject Table] - Table/entity under compliance audit. Simple string, not a denormalized blob or join.
  subject_table String

  /// [Subject ID] - Affected entity row UUID. Normalized linkage.
  subject_id String @db.Uuid

  /// [Status] - Status value (e.g., "pending", "approved", "rejected"). Maintains normalization by single value per event.
  status String

  /// [Notes/Context] - Atomic audit context. Purely descriptive.
  notes String

  /// [Audit Created] - When the compliance event occurred.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin ai_ecommerce_administrator? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@unique([audit_type, subject_id])
  @@index([admin_id, created_at])
  @@index([notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Daily Statistics - Materialized View] - Implements denormalized, pre-computed daily platform statistics for reporting/performance from architecture requirements.
///
/// Caches day-level aggregates (total orders, revenue, logins, etc.) for analytics dashboards. Normalization is intentionally relaxed (denormalization allowed) for read efficiency; raw detail persists in normalized tables. Example: reporting yesterday’s sales/orders across platform.
///
/// Key relationships: Read-only view; not updated directly. Special behaviors: auto-refresh, never modified by app logic, aggregates by date.
///
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_mv_daily_stats {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Row identifier for aggregation row.
  id String @id @db.Uuid

  /// [Statistic Date] - Date of the statistics (ISO date stored as string).
  stat_date String

  /// [Order Count] - Number of orders on this date. Denormalized aggregation.
  order_count Int @db.Integer

  /// [Revenue Amount] - Total sales in double on that date. Denormalized.
  revenue_amount Float @db.DoublePrecision

  /// [Login Count] - Number of unique account logins that day. Denormalized.
  login_count Int @db.Integer

  /// [Signups Count] - Total user signups. Denormalized.
  signups_count Int @db.Integer

  /// [Review Count] - Number of new reviews. Denormalized.
  review_count Int @db.Integer

  //----
  // RELATIONS
  //----
  @@unique([stat_date])
}

/// [Trending Products - Materialized View] - Implements denormalized, pre-computed trending product statistics from analytics and AI documentation.
///
/// Tracks high-performing products by day/week/month for recommendation, featuring, and dashboards. Normalization is relaxed; aggregates like rank, counts, and composite scores are pre-computed here. Example: Populating “Trending Now” on homepage.
///
/// Key relationships: Links to product entity by foreign key; not written by app logic. Special behaviors: refreshed/cached, used for automated scripts or admin apps.
///
/// Usage example: Home feed queries trending products with a given rank/period.
///
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_mv_trending_products {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique trending record id.
  id String @id @db.Uuid

  /// [Product FK] - Links to trending product row.
  /// Maintains foreign key link for analytics/drilldown.
  /// Read-only.
  product_id String @db.Uuid

  /// [Period] - Denormalized period (e.g., "daily", "weekly", "monthly").
  stat_period String

  /// [Date] - Day/week/month this trending record covers, ISO date format.
  stat_date String

  /// [Trend Rank] - Position of product in trending list. Pre-computed.
  trend_rank Int @db.Integer

  /// [Sales Count] - Sum of all sales during stat period.
  sales_count Int @db.Integer

  /// [Views Count] - Count of product views.
  views_count Int @db.Integer

  /// [Composite Score] - Pre-computed score based on custom trending algorithm.
  composite_score Float @db.DoublePrecision

  //----
  // RELATIONS
  //----
  product ai_ecommerce_product @relation(fields: [product_id], references: [id], onDelete: Cascade)

  @@index([product_id])

  @@unique([stat_period, stat_date, product_id])
  @@index([trend_rank, stat_period, stat_date])
}

/// [Unified Platform Audit Log] - Implements the architecture, compliance, and audit requirements found in '10_ai_ecommerce_architecture_compliance_future.md'.
///
/// Captures an immutable, append-only log of significant user, admin, and system actions across the platform for regulatory, security, and operational auditability. Ensures 3NF: each row is a single, atomic audit event; any aggregations must be handled in analytics layers or denormalized materialized views. For example, records each login attempt, permission change, product update, or sensitive data access with contextual links to the actor and target object. 
///
/// Key relationships: Flexible polymorphic actor FKs for customer, seller, or admin. Optionally references a target business object by table and ID. 
/// Special behaviors: Immutable post-insertion, soft-delete for compliance, supports text search on action context.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_audit_log {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Implements unique audit log identity. Required for traceable tamper-proof records.
  id String @id @db.Uuid

  /// [Polymorphic Customer Actor FK] - Links to ai_ecommerce_customer. Null if not a customer actor. Implements actor traceability. Maintains 3NF by not copying info.
  actor_customer_id String? @db.Uuid

  /// [Polymorphic Seller Actor FK] - Links to ai_ecommerce_seller. Null if not a seller actor. Maintains normalized audit actor linkage.
  actor_seller_id String? @db.Uuid

  /// [Polymorphic Admin Actor FK] - Links to ai_ecommerce_administrator. Null if not an admin actor. Tracks privileged/critical actions for governance.
  actor_admin_id String? @db.Uuid

  /// [Action Type] - Atomic event type (e.g., 'login', 'order_edit'). Implements clear activity taxonomy for audit traceability. Fully normalized.
  action_type String

  /// [Target Business Table] - Entity impacted by the action (e.g., 'ai_ecommerce_order'). Ensures audit normalization - no redundant object state.
  target_table String

  /// [Target Entity ID] - UUID of the specific business object affected. Enables joining with affected entity snapshots.
  target_id String @db.Uuid

  /// [Event Description] - Atomic context note (e.g., 'Seller profile updated.'). Used for compliance search/audit workflows. No aggregation.
  description String

  /// [Created At] - Timestamp the audit record was written. Required for chronological forensics and compliance.
  created_at DateTime @db.Timestamptz

  /// [Soft Delete At] - Soft-delete timestamp, enables legal/PII removal without full DB erasure. Null if not logically deleted.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_ecommerce_customer? @relation(fields: [actor_customer_id], references: [id], onDelete: Cascade)
  seller ai_ecommerce_seller? @relation(fields: [actor_seller_id], references: [id], onDelete: Cascade)
  admin ai_ecommerce_administrator? @relation(fields: [actor_admin_id], references: [id], onDelete: Cascade)

  @@index([actor_customer_id, created_at])
  @@index([actor_seller_id, created_at])
  @@index([actor_admin_id, created_at])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [System Integration/Event Log] - Implements the event-driven system traceability required by '10_ai_ecommerce_architecture_compliance_future.md' and microservice orchestration documentation.
///
/// Logs each discrete system or integration event (domain event, system callback, webhook, etc.) for traceability, debugging, and real-time analytics. Maintains 3NF: every row covers a single atomic event; payload is logged as JSON string, but no business denormalization. For example: records payment webhook callbacks, domain event emission, or cross-service notifications.
///
/// Key relationships: Optionally reference a business target entity or table. 
/// Special behaviors: Append-only, non-editable after insertion, heavily indexed for event analytics and debugging. Enables temporal and cause/effect analysis of workflows.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_system_event {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique per event; required for log integrity.
  id String @id @db.Uuid

  /// [Event Type] - E.g., 'order_created', 'payment_callback'. Atomic string for event domain.
  event_type String

  /// [Target Table] - Optional. Name of business table affected (e.g., 'ai_ecommerce_order').
  target_table String

  /// [Target Entity ID] - Optional. UUID of affected row within business table.
  target_id String @db.Uuid

  /// [Payload JSON] - Atomic JSON payload. Contains serialized business data for audit/debug. Maintains normalization as string, not object.
  payload_json String

  /// [Created At] - Timestamp for the event log row. Ensures proper time-based event replay and analytics.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_type, created_at])
  @@index([payload_json(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// [Compliance Audit Log] - Implements regulatory, privacy, and compliance event recording as mandated in '10_ai_ecommerce_architecture_compliance_future.md' and system-wide audit rules.
///
/// Stores atomic records for each compliance-relevant action: data erasure requests, policy review, PII access, payment exception handling. Strict 3NF: every row is a discrete regulatory event; all analytics run over this or denormalized views. Example events: GDPR delete, KISA log review, or PCI DSS audit.
///
/// Key relationships: May reference the administrator (admin_id) responsible for the compliance action (nullable if system-initiated). 
/// Special behaviors: Non-editable, immutable, supporting advanced context full-text search via GIN.
///
/// @namespace AuditAnalytics
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_compliance_audit {
  //----
  // COLUMNS
  //----
  /// [Primary Key] - Unique compliance audit log row.
  id String @id @db.Uuid

  /// [Admin FK] - References ai_ecommerce_administrator for action accountability. Nullable if automated policy action. Maintains normalization with role-based linkage.
  admin_id String? @db.Uuid

  /// [Audit Type] - Nature of the event (e.g., 'GDPR_DELETE', 'PCI_REVIEW'). Single normalized action type.
  audit_type String

  /// [Subject Table] - Name of affected table or business entity (e.g., 'ai_ecommerce_customer').
  subject_table String

  /// [Subject ID] - UUID of entity under audit.
  subject_id String @db.Uuid

  /// [Status] - Outcome, e.g., 'pending', 'processed', 'approved', 'rejected'. Maintains normalization, ties to audit process states.
  status String

  /// [Notes/Context] - Freeform, atomic compliance justification/context. No aggregation/pre-calculation.
  notes String

  /// [Created At] - Timestamp for write-once compliance record.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin ai_ecommerce_administrator? @relation(fields: [admin_id], references: [id], onDelete: Cascade)

  @@unique([audit_type, subject_id])
  @@index([admin_id, created_at])
  @@index([notes(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.main.prisma:
