  order_channel String?

  /// [Placed At Timestamp] - When the order was created/checked out, ensuring proper sequencing.
  placed_at DateTime @db.Timestamptz

  /// [Last Updated] - Tracks state transitions, including cancellations, returns, or fulfillment action.
  updated_at DateTime @db.Timestamptz

  /// [Soft Delete] - Enables compliance/audit removal, keeping record for legal review.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_ecommerce_order_customer         ai_ecommerce_customer     @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  ai_ecommerce_order_cart             ai_ecommerce_cart         @relation(fields: [cart_id], references: [id], onDelete: Cascade)
  ai_ecommerce_order_shipping_address ai_ecommerce_user_address @relation(fields: [shipping_address_id], references: [id], onDelete: Cascade)

  ai_ecommerce_inquiry            ai_ecommerce_inquiry[]
  ai_ecommerce_review             ai_ecommerce_review[]
  ai_ecommerce_order_item         ai_ecommerce_order_item[]
  ai_ecommerce_order_status_log   ai_ecommerce_order_status_log[]
  ai_ecommerce_shipment           ai_ecommerce_shipment?
  ai_ecommerce_return_request     ai_ecommerce_return_request[]
  ai_ecommerce_loyalty_point      ai_ecommerce_loyalty_point[]
  ai_ecommerce_wallet_transaction ai_ecommerce_wallet_transaction[]

  @@unique([cart_id])
  @@index([shipping_address_id])
  @@index([customer_id, placed_at])
