  ai_ecommerce_order_item_order ai_ecommerce_order @relation(fields: [order_id], references: [id], onDelete: Cascade)
  ai_ecommerce_order_item_sku   ai_ecommerce_sku   @relation(fields: [sku_id], references: [id], onDelete: Cascade)

  @@unique([order_id, sku_id])
  @@index([sku_id])
