  @@index([order_id, status])
}

schemas.schema-06_discount_loyalty_payment.prism:
/// Coupon entity - Implements the 'Discount System' and 'Coupon Issuance/Usage' requirements from 08_ai_ecommerce_discount_loyalty_payment.md.
///
/// Represents platform- or seller-issued coupons distributed to customers for redemption. Fully normalized: only core coupon data, no calculated aggregates or usage counts (these are in materialized views). For example, enables application of seller promotions and supports eligibility checks, referencing customers, sellers, and rules.
///
/// Key relationships: References issuing seller, owning customer, and related discount rule. Special behaviors: Enforces single/multi-use logic via unique index on (code, customer_id).
///
/// @namespace DiscountLoyaltyPayment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_coupon {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Each coupon is uniquely addressable.
  id String @id @db.Uuid

  /// [Customer ownership] - Links coupon to intended customer, for personalized coupons. Nullable for platform-wide distribution.
  customer_id String? @db.Uuid

  /// [Issuing seller] - Seller that issued this coupon. Nullable for platform coupons.
  seller_id String? @db.Uuid

  /// [Discount rule linkage] - Connects coupon with its discount definition logic.
  discount_rule_id String @db.Uuid

  /// [Coupon code] - Unique identification used by customer at redemption.
  ///
  /// Uniqueness enforced per customer/scope. E.g., SAVE10.
  code String

  /// [Issued timestamp] - When coupon was issued.
  issued_at DateTime @db.Timestamptz

  /// [Expiration] - When coupon is no longer valid.
  expires_at DateTime? @db.Timestamptz

  /// [Active flag] - Whether coupon is available for redemption.
  is_active Boolean

  /// [Usage count limit] - How many times coupon can be redeemed.
  usage_limit Int @db.Integer

  /// [Per-customer limit] - Max redemptions by single customer.
  usage_per_customer_limit Int @db.Integer

  //----
  // RELATIONS
  //----
  customer_coupon ai_ecommerce_customer?     @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  seller_coupon   ai_ecommerce_seller?       @relation(fields: [seller_id], references: [id], onDelete: Cascade)
  rule_coupon     ai_ecommerce_discount_rule @relation(fields: [discount_rule_id], references: [id], onDelete: Cascade)

  @@unique([code, customer_id])
  @@index([customer_id])
  @@index([discount_rule_id])
  @@index([seller_id, discount_rule_id])
}

/// Loyalty point record - Implements 'Loyalty Management: Reward/Spend' in 08_ai_ecommerce_discount_loyalty_payment.md.
///
/// Records loyalty point accrual or redemption event per customer. Strictly normalized: no running balance fields. Supports programmatic auditing and dispute resolution.
