/// Wallet transaction record - Implements 'Deposit/Spend/Refund' from 08_ai_ecommerce_discount_loyalty_payment.md.
///
/// Each record documents a wallet inflow/outflow; strictly normalized with no pre-calculated/cached balances. Enables full, auditable history for customer and compliance.
///
/// Key relationships: Linked to wallet, optionally to order/payment. All types: deposit/payment/refund/etc.
///
/// @namespace DiscountLoyaltyPayment
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_ecommerce_wallet_transaction {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique per wallet transaction.
  id String @id @db.Uuid

  /// [Wallet] - Wallet owning this transaction.
  wallet_id String @db.Uuid

  /// [Order linkage] - Related order if available.
  order_id String? @db.Uuid

  /// [Payment linkage] - Payment event if available.
  payment_id String? @db.Uuid

  /// [Amount changed] - Money credited or debited for this transaction.
  change_amount Float @db.DoublePrecision

  /// [Currency] - ISO 4217 code.
  currency_code String

  /// [Type] - e.g., 'deposit', 'payment', 'refund', etc.
  transaction_type String

