model ai_ecommerce_payment_integration {
  //----
  // COLUMNS
  //----
  /// [Primary key] - Unique integration config.
  id String @id @db.Uuid

  /// [Provider] - E.g., Stripe, KCP, KakaoPay.
  provider_name String

  /// [Config blob] - Stores JSON settings and encrypted keys.
  configuration_json String

  /// [Status] - Whether this integration is available.
  is_active Boolean

  /// [Timestamp] - When configured/updated.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@unique([provider_name])
